-- Force Postgres to use DP enumeration (disable GEQO)
SET geqo = off;

-- Show Postgres join reordering is active
SET join_collapse_limit = 8;  -- reorder joins up to this count

-- Disable reordering to use the FROM clause order as-is
SET join_collapse_limit = 1;

-- With DP enabled, EXPLAIN shows Postgres's chosen order
EXPLAIN
SELECT * FROM a JOIN b ON a.id = b.a_id
             JOIN c ON c.b_id = b.id;

// Volcano iterator interface
interface Iterator {
    open()         // initialise state; recursively open children
    next() -> Row  // return next row, or EOF when exhausted
    close()        // release resources; recursively close children
}

// Execution: client drives the loop
root.open()
while true:
    row = root.next()   // cascades down to scan leaves
    if row == EOF: break
    send_to_client(row)
root.close()

-- Encourage hash join by ensuring statistics are fresh
ANALYZE orders;
ANALYZE customers;

-- Increase work_mem to keep hash table in memory
SET work_mem = '256MB';

EXPLAIN ANALYZE
SELECT o.id, c.name
FROM   orders o
JOIN   customers c ON o.cust_id = c.id;

-- Look for: Hash Join ... Hash Cond: (o.cust_id = c.id)
-- Then:     Hash  (cost=... rows=100000 ...)
--             SeqScan on customers  ← build side (smaller)

-- Force a sequential scan to compare cost
SET enable_indexscan  = off;
SET enable_bitmapscan = off;

EXPLAIN ANALYZE
SELECT * FROM orders WHERE status = 'active';
-- Observe actual ms; re-enable and compare with index path.

SET enable_indexscan  = on;
SET enable_bitmapscan = on;

-- Tune the crossover point for SSDs:
SET random_page_cost = 1.1;   -- makes index scan more attractive

-- Postgres uses NSM (row store) by default.
-- Inspect a raw page to see row layout:
CREATE EXTENSION pageinspect;

SELECT lp, t_xmin, t_xmax, t_data
FROM   heap_page_items(get_raw_page('orders', 0))
LIMIT  5;
-- Each row's t_data contains ALL columns packed together.

-- Covering index mimics DSM projection for specific queries:
CREATE INDEX ON orders (region) INCLUDE (amount);
-- Index-Only Scan reads only (region, amount) — no heap fetch.

-- Full analyze of a single table
ANALYZE orders;

-- Targeted analyze of specific columns (faster)
ANALYZE orders (amount, region, order_date);

-- Raise statistics resolution for a skewed column
ALTER TABLE orders
  ALTER COLUMN amount SET STATISTICS 500;
ANALYZE orders (amount);

-- Check when a table was last analyzed
SELECT relname, last_analyze, last_autoanalyze
FROM   pg_stat_user_tables
WHERE  relname = 'orders';

-- Create a range-partitioned table on order_date
CREATE TABLE orders (
    id         BIGINT,
    order_date DATE,
    amount     NUMERIC
) PARTITION BY RANGE (order_date);

CREATE TABLE orders_2024_01
  PARTITION OF orders
  FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');

-- Query that triggers partition pruning:
EXPLAIN
SELECT * FROM orders WHERE order_date = '2024-01-15';
-- Postgres scans only orders_2024_01; other partitions pruned.

-- Check if GEQO is active and its threshold
SHOW geqo;             -- on
SHOW geqo_threshold;   -- 12 (switch to GEQO for >= 12 tables)

-- Lower threshold to bound planning time for complex views
SET geqo_threshold = 8;

-- Disable GEQO to force exhaustive DP (use for testing only)
SET geqo = off;

-- Force explicit join order (bypass both DP and GEQO)
SET join_collapse_limit = 1;

-- Create an expression index for case-insensitive search
CREATE INDEX users_email_lower_idx
  ON users (LOWER(email));

-- This query now uses the index:
SELECT * FROM users WHERE LOWER(email) = 'alice@example.com';

-- Expression index on JSON attribute:
CREATE INDEX ON events ((payload ->> 'user_id'));
SELECT * FROM events WHERE (payload ->> 'user_id') = '42';

-- Partial expression index (combines both features):
CREATE INDEX ON orders (DATE_TRUNC('month', order_date))
  WHERE status = 'completed';

-- Scenario: T1 runs at REPEATABLE READ level in Postgres
-- (Postgres REPEATABLE READ = Snapshot Isolation — no phantoms)

BEGIN ISOLATION LEVEL REPEATABLE READ;

-- First range scan: finds 5 rows
SELECT COUNT(*) FROM orders WHERE amount > 1000;
-- Result: 5

-- Meanwhile, T2 inserts a new row with amount = 2000 and COMMIT

-- Second range scan within same transaction:
SELECT COUNT(*) FROM orders WHERE amount > 1000;
-- Postgres result: 5  (snapshot prevents phantom)
-- MySQL READ COMMITTED result: 6  (phantom row visible)

COMMIT;
